package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;
import java.util.zip.CRC32C;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalMetadataMemoryTest {

	@TempDir
	Path directory;

	@Test
	void boundsTypeAndKindStringsInSmallHeap() throws Exception {
		runProbe("codes");
	}

	@Test
	void boundsNumericMetadataStringsInSmallHeap() throws Exception {
		runProbe("numbers");
	}

	@Test
	void preservesScalarMetadataCoercions() throws Exception {
		try (OutputStream output = Files.newOutputStream(directory.resolve("wal-1.v1"))) {
			writeFrame(output, "{\"t\":\"V\",\"segment\":1,\"firstId\":1}");
			writeFrame(output,
					"{\"t\":\"Mint\",\"lsn\":\"42.9\",\"id\":\"3e0\",\"vk\":\"Bnode\",\"lex\":\"one\",\"hash\":true}");
			writeFrame(output,
					"{\"t\":\"M\",\"lsn\":\"null\",\"id\":true,\"vk\":\"B\",\"lex\":\"two\",\"hash\":null}");
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config(directory))) {
			var records = reader.scan().records();
			assertThat(records).hasSize(2);
			assertThat(records.get(0).lsn()).isEqualTo(42);
			assertThat(records.get(0).id()).isEqualTo(3);
			assertThat(records.get(0).hash()).isEqualTo(1);
			assertThat(records.get(1).lsn()).isZero();
			assertThat(records.get(1).id()).isEqualTo(1);
			assertThat(records.get(1).hash()).isZero();
		}
	}

	private void runProbe(String mode) throws Exception {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path log = directory.resolve(mode + ".log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-Xmx32m", "-XX:+ExitOnOutOfMemoryError", "-cp", classpath,
				ValueStoreWalMetadataMemoryTest.class.getName(), directory.resolve(mode).toString(), mode)
						.redirectErrorStream(true)
						.redirectOutput(log.toFile())
						.start();
		try {
			assertThat(process.waitFor(60, TimeUnit.SECONDS)).as("Metadata probe must finish").isTrue();
			assertThat(process.exitValue()).withFailMessage("Metadata memory probe failed:%n%s", Files.readString(log))
					.isZero();
		} finally {
			process.destroyForcibly();
		}
	}

	public static void main(String[] args) throws Exception {
		Path directory = Files.createDirectories(Path.of(args[0]));
		String[] fields = "codes".equals(args[1]) ? new String[] { "t", "vk" }
				: new String[] { "lsn", "id", "lastId", "hash", "crc32" };
		for (String field : fields) {
			writeLargeMetadata(directory.resolve("wal-1.v1"), field);
			try (ValueStoreWalReader reader = ValueStoreWalReader.open(config(directory))) {
				try {
					reader.summarize();
					throw new AssertionError("Oversized metadata must fail explicitly: " + field);
				} catch (ValueStoreWalMemory.LimitExceededException expected) {
					System.out.println("BOUNDED_METADATA_" + field);
				}
			}
		}
	}

	private static ValueStoreWalConfig config(Path directory) {
		return ValueStoreWalConfig.builder().walDirectory(directory).storeUuid("metadata-memory").build();
	}

	private static void writeLargeMetadata(Path path, String field) throws IOException {
		byte[] prefix = ("{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"safe\",\"" + field + "\":\"")
				.getBytes(StandardCharsets.UTF_8);
		byte[] suffix = "\"}".getBytes(StandardCharsets.UTF_8);
		int length = 64 * 1024 * 1024;
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(path))) {
			writeFrame(output, "{\"t\":\"V\",\"segment\":1,\"firstId\":1}");
			writeIntLE(output, prefix.length + length + suffix.length);
			CRC32C crc = new CRC32C();
			output.write(prefix);
			crc.update(prefix, 0, prefix.length);
			byte[] block = new byte[8192];
			Arrays.fill(block, (byte) 'x');
			for (int written = 0; written < length; written += block.length) {
				output.write(block);
				crc.update(block, 0, block.length);
			}
			output.write(suffix);
			crc.update(suffix, 0, suffix.length);
			writeIntLE(output, (int) crc.getValue());
		}
	}

	private static void writeFrame(OutputStream output, String json) throws IOException {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		writeIntLE(output, bytes.length);
		output.write(bytes);
		writeIntLE(output, (int) crc.getValue());
	}

	private static void writeIntLE(OutputStream output, int value) throws IOException {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
